 private void readLive(){try{String s=livePrefs.getString(TelemetryServiceV10.KEY_LATEST,"");long u=livePrefs.getLong("updatedAt",0);if(!s.isEmpty()&&System.currentTimeMillis()-u<10000)live=new JSONObject(s);else live=fallback();}catch(Exception e){live=fallback();}updateHeader();update();int ev=live.optInt("plugEventId",-1);if(plugged()&&ev>=0&&ev!=lastPlug){lastPlug=ev;ui.edit().putInt("handledPlug",ev).apply();h.postDelayed(this::autoSetup,400);}}
 private JSONObject fallback(){JSONObject j=new JSONObject();try{Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));BatteryManager bm=(BatteryManager)getSystemService(BATTERY_SERVICE);int l=b.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),sc=b.getIntExtra(BatteryManager.EXTRA_SCALE,100),pl=b.getIntExtra(BatteryManager.EXTRA_PLUGGED,0),st=b.getIntExtra(BatteryManager.EXTRA_STATUS,1),mv=b.getIntExtra(BatteryManager.EXTRA_VOLTAGE,-1),ua=bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CURRENT_NOW);boolean pg=pl!=0,ch=pg&&(st==2||st==5);j.put("plugged",pg);j.put("charging",ch);if(l>=0)j.put("phonePct",100.0*l/sc);if(mv>0)j.put("batteryV",mv/1000.0);if(ua!=Integer.MIN_VALUE){j.put("batteryMa",ua/1000.0);if(mv>0)j.put("batteryW",(ch?1:-1)*Math.abs(mv/1000.0*ua/1e6));}}catch(Exception ignored){}return j;}

