 private void update(){if(tab==Tab.OVERVIEW)uOverview();else if(tab==Tab.LIVE)uLive();else if(tab==Tab.HISTORY){set("hc",""+HistoryStore.count(this));set("hr",range==0?"Gesamt":rangeText(range));set("he",fo("cycleWh","Wh"));charts();}else if(tab==Tab.REPORT)uReport();}
 private void updateHeader(){ProfileStore.Profile p=ps.getActive();header.setText(!plugged()?"● Akkubetrieb · "+f0(v("phonePct"))+" %":(bool("charging")?"● Laden aktiv · ":"● Quelle verbunden · ")+(p==null?"nicht zugeordnet":p.name)+" · "+f0(v("phonePct"))+" %");header.setTextColor(plugged()?OK:MUTED);}
 private void uOverview(){set("state",plugged()?(bool("charging")?"LIVE · Laden aktiv":"LIVE · Quelle verbunden"):"LIVE · Akkubetrieb");set("phone",fo("phonePct","%"));set("net",fo("batteryW","W"));ProfileStore.Profile p=ps.getActive(),c=ps.getActiveCable();set("source",p==null?"nicht zugeordnet":p.name);set("cable",c==null?"nicht zugeordnet":c.name);BridgeStore.Bridge b=bs.active();set("bridge",b==null?"keine":b.name);double rem=v("aggregateRemainingWh"),full=v("aggregateFullWh"),soc=v("aggregateSoc");set("agg",ok(soc)?f0(soc)+" %":"— %");set("aggwh",ok(rem)?f1(rem)+" Wh verfügbar · "+f1(full)+" Wh bekannt":"keine bestätigte Gesamtkapazität");double bw=v("batteryW"),sw=v("sourceExactW"),sa=v("sourceA");set("resPhone",ok(bw)?f2(bw)+" W":"—");double cl=Double.NaN;if(c!=null&&ok(sa)&&!Double.isNaN(c.cableResistanceOhm))cl=sa*sa*c.cableResistanceOhm;set("resCable",ok(cl)?f3(cl)+" W":"nicht direkt messbar");double loss=ok(sw)&&ok(bw)?Math.max(0,Math.abs(sw)-Math.abs(bw)):Double.NaN;set("resLoss",ok(loss)?f2(loss)+" W":"nicht direkt messbar");set("resBridge",b==null?"keine Bridge":bridgeWh(b));double d=drain();if(d>0&&ok(rem)){set("runtime",hours(rem/d));set("basis","Basis "+f2(d)+" W · "+(ui.getFloat("manualW",0)>0?"manuell bestätigt":"Live-Mittel Entladung"));}else{set("runtime","—");set("basis","Im Akkubetrieb messen oder Referenzverbrauch eintragen.");}}
 private void uLive(){double ma=v("batteryMa"),a=ok(ma)?ma/1000:Double.NaN,w=v("batteryW");set("ma",ok(ma)?f0(Math.abs(ma))+" mA":"— mA");set("aw",(ok(a)?f3(a)+" A":"— A")+" · "+(ok(w)?f2(w)+" W":"— W"));set("livestate",plugged()?(bool("charging")?"Laden aktiv · LIVE":"Quelle verbunden · kein Ladefluss"):"Akkubetrieb · negative Werte = Entladung");set("lphone",fo("phonePct","%"));set("lv",fo("batteryV","V"));set("la",ok(a)?f3(a)+" A":"—");set("lw",fo("batteryW","W"));set("lt",fo("temperatureC","°C"));set("lc",fo("chargeCounterMah","mAh"));ProfileStore.Profile p=ps.getActive();set("sname",p==null?"nicht zugeordnet":p.name);set("sv",ok(v("sourceV"))?f3(v("sourceV"))+" V · "+live.optString("sourceVPath",""):"nicht verfügbar");set("sa",ok(v("sourceA"))?f3(v("sourceA"))+" A · "+live.optString("sourceAPath",""):"nicht verfügbar");set("sw",ok(v("sourceExactW"))?f2(v("sourceExactW"))+" W DIREKT":(ok(v("sourceEffectiveW"))?f2(v("sourceEffectiveW"))+" W modelliert":"—"));set("ssoc",p!=null&&p.isEnergyStore()&&p.socKnown?f0(p.estimatedSoc)+" % · "+p.socOrigin:"nicht bestätigt");set("smax",fo("profileMaxV","V")+" / "+fo("profileMaxA","A")+" MAX");charts();}
 private void uReport(){set("rp",plugged()?"JA":"NEIN");set("rc",bool("charging")?"JA":"NEIN");set("rv",ok(v("sourceV"))?f3(v("sourceV"))+" V":"UNAVAILABLE");set("ra",ok(v("sourceA"))?f3(v("sourceA"))+" A":"UNAVAILABLE");set("rprof",ps.load().size()+" gesamt");set("rbr",bs.load().size()+" gesamt");set("rh",HistoryStore.count(this)+" Punkte");String x="";if(!ok(v("sourceV")))x+="P0 · VBUS nicht direkt verfügbar.\n";if(!ok(v("sourceA")))x+="P0 · IBUS nicht direkt verfügbar.\n";for(ProfileStore.Profile p:ps.loadActiveInventory())if(p.isEnergyStore()&&!p.socKnown)x+="P1 · SOC unbekannt: "+p.name+"\n";set("issues",x.isEmpty()?"Keine offenen Datenprobleme.":x);}

 private void autoSetup(){String sig=live.optString("signature","");List<ProfileStore.Profile> m=ps.matchingSignature(sig);ProfileStore.Profile p=m.size()==1?m.get(0):null;if(p!=null)ps.setActiveId(p.id);setup(p,true);}private void setup(ProfileStore.Profile p,boolean first){Intent i=new Intent(this,SetupWizardActivity.class);if(p!=null)i.putExtra("profileId",p.id);i.putExtra("firstUse",first);startActivityForResult(i,SETUP);}private void bridge(BridgeStore.Bridge b){Intent i=new Intent(this,BridgeWizardActivity.class);if(b!=null)i.putExtra("bridgeId",b.id);startActivityForResult(i,BRIDGE);}
 @Override protected void onActivityResult(int r,int s,Intent d){super.onActivityResult(r,s,d);if(r==SETUP&&s==RESULT_OK){show(tab);if(bs.active()==null&&energy().size()>=2)h.postDelayed(()->bridge(null),350);}else if(r==BRIDGE&&s==RESULT_OK)show(Tab.BRIDGE);else if(r==IMPORT&&s==RESULT_OK&&d!=null)importHistory(d.getData());else if(r==EXPORT&&s==RESULT_OK&&d!=null)writeExport(d.getData());}
 private void pickImport(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}private void importHistory(Uri u){int n=0;try{BufferedReader r=new BufferedReader(new InputStreamReader(getContentResolver().openInputStream(u)));StringBuilder a=new StringBuilder();String l;while((l=r.readLine())!=null)a.append(l).append('\n');String s=a.toString().trim();if(s.startsWith("[")){JSONArray q=new JSONArray(s);for(int i=0;i<q.length();i++){HistoryStore.append(this,HistoryStore.Point.fromJson(q.getJSONObject(i)));n++;}}else if(s.startsWith("{")){JSONObject o=new JSONObject(s);JSONArray q=o.optJSONArray("history");if(q!=null)for(int i=0;i<q.length();i++){HistoryStore.append(this,HistoryStore.Point.fromJson(q.getJSONObject(i)));n++;}else{HistoryStore.append(this,HistoryStore.Point.fromJson(o));n++;}}else for(String x:s.split("\\n"))if(!x.trim().isEmpty()){HistoryStore.append(this,HistoryStore.Point.fromJson(new JSONObject(x)));n++;}Toast.makeText(this,n+" Punkte importiert",1).show();show(Tab.HISTORY);}catch(Exception e){Toast.makeText(this,"Import fehlgeschlagen: "+e.getMessage(),1).show();}}
 private void export(){try{JSONObject o=new JSONObject();o.put("app","CCOP LadeMonitor v11 VERIFIED WORKFLOW");o.put("createdAt",System.currentTimeMillis());o.put("live",live);JSONArray p=new JSONArray();for(ProfileStore.Profile x:ps.load())p.put(x.toJson());o.put("profiles",p);JSONArray b=new JSONArray();for(BridgeStore.Bridge x:bs.load())b.put(x.toJson());o.put("bridges",b);o.put("historyCount",HistoryStore.count(this));exportText=o.toString(2);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"ccop-v11-"+new SimpleDateFormat("yyyyMMdd-HHmm",Locale.GERMANY).format(new Date())+".json");startActivityForResult(i,EXPORT);}catch(Exception ignored){}}private void writeExport(Uri u){try{OutputStream o=getContentResolver().openOutputStream(u);o.write(exportText.getBytes("UTF-8"));o.close();}catch(Exception ignored){}}

 private View phoneRow(){LinearLayout r=row();LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.addView(t("Smartphone",15,TEXT,true));double full=ps.getPhoneCapacityMah()/1000*ps.getPhoneNominalV(),pct=v("phonePct"),rest=ok(pct)?full*pct/100:Double.NaN,d=drain();l.addView(t((ok(pct)?f0(pct)+" % · "+f1(rest)+" Wh":"SOC ?")+(d>0&&ok(rest)?" · "+hours(rest/d):""),11,CYAN,false));r.addView(l,new LinearLayout.LayoutParams(0,-2,1));return r;}private View invRow(ProfileStore.Profile p){LinearLayout r=row();r.addView(photo(p),new LinearLayout.LayoutParams(dp(58),dp(58)));LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(8),0,0,0);l.addView(t(p.name,15,TEXT,true));l.addView(t(p.type+" · "+p.deviceHash,10,MUTED,false));if(p.isEnergyStore()){double rest=p.socKnown?p.capacityWh()*p.estimatedSoc/100:Double.NaN,d=drain();l.addView(t(p.socKnown?f0(p.estimatedSoc)+" % · "+f1(rest)+" Wh"+(d>0?" · "+hours(rest/d):""):"SOC unbekannt",11,p.socKnown?CYAN:WARN,false));}r.addView(l,new LinearLayout.LayoutParams(0,-2,1));r.setOnClickListener(v->setup(p,false));return r;}private LinearLayout row(){LinearLayout r=new LinearLayout(this);r.setGravity(16);r.setPadding(0,dp(7),0,dp(7));return r;}private ImageView photo(ProfileStore.Profile p){ImageView i=new ImageView(this);i.setScaleType(ImageView.ScaleType.CENTER_CROP);i.setBackground(round(Color.rgb(9,20,28),LINE,10));if(!p.photoUris.isEmpty())try{i.setImageURI(Uri.parse(p.photoUris.get(0)));}catch(Exception e){i.setImageResource(android.R.drawable.ic_menu_gallery);}else i.setImageResource(android.R.drawable.ic_menu_gallery);return i;}
 private List<ProfileStore.Profile> energy(){ArrayList<ProfileStore.Profile>a=new ArrayList<>();for(ProfileStore.Profile p:ps.loadActiveInventory())if(p.isEnergyStore())a.add(p);return a;}private double drain(){float m=ui.getFloat("manualW",0);if(m>0)return m;List<HistoryStore.Point> a=HistoryStore.readSince(this,System.currentTimeMillis()-1800000,0);double s=0;int n=0;for(HistoryStore.Point p:a)if(!p.plugged&&ok(p.batteryW)&&p.batteryW<-.05){s+=Math.abs(p.batteryW);n++;}return n>0?s/n:(!plugged()&&v("batteryW")<-.05?Math.abs(v("batteryW")):0);}private String desc(BridgeStore.Bridge b){return"A: "+name(b.batteryAId)+" · B: "+name(b.batteryBId)+"\nKabel: "+name(b.cableId)+" · Quelle: "+name(b.sourceId)+" · "+b.mode+" · "+bridgeWh(b);}private String bridgeWh(BridgeStore.Bridge b){ProfileStore.Profile a=ps.getById(b.batteryAId),c=ps.getById(b.batteryBId);double w=0;if(a!=null&&a.socKnown)w+=a.capacityWh()*a.estimatedSoc/100;if(c!=null&&c.socKnown)w+=c.capacityWh()*c.estimatedSoc/100;return f1(w)+" Wh Rest";}private String name(String id){ProfileStore.Profile p=ps.getById(id);return p==null?"—":p.name;}
